def construct_bracket_sequence(n, k):
    if k > n * (n + 1) // 2:
        return "Impossible"

    result = []
    open_brackets = 0
    total_nesting = 0

    for i in range(2 * n):
        if total_nesting + open_brackets < k:
            result.append('(')
            open_brackets += 1
            total_nesting += open_brackets - 1
        else:
            result.append(')')
            open_brackets -= 1
            total_nesting -= 1

    return ''.join(result)

# Read input
n, k = map(int, input().split())

# Output the result
print(construct_bracket_sequence(n, k))
